<?php namespace App\Services; use App\Repositories\AuditoriaRepository; class AuditoriaService { public function __construct(private AuditoriaRepository $repo) {} public function log(string $acao,string $entidade,string $id,string $descricao):void {$this->repo->create(['loja_id'=>session('loja_id'),'usuario_id'=>session('usuario_id'),'acao'=>$acao,'entidade'=>$entidade,'entidade_id'=>$id,'descricao'=>$descricao,'data_hora'=>now()->toIso8601String()]);} }
